import React, { useState } from 'react';

const SecretPhraseStrengthGauge = () => {
  const [phrase, setPhrase] = useState('');
  const [strength, setStrength] = useState('weak');

  const handleInputChange = (event) => {
    const newPhrase = event.target.value;
    setPhrase(newPhrase);
    if (newPhrase.length < 8) {
      setStrength('weak');
    } else if (newPhrase.length >= 8 && newPhrase.length <= 16) {
      setStrength('medium');
    } else {
      setStrength('strong');
    }
  };

  return (
    <div>
      <input type="password" value={phrase} onChange={handleInputChange} placeholder="Enter secret phrase" />
      <p className={`strength-${strength}`}>{strength}</p>
    </div>
  );
};

export default SecretPhraseStrengthGauge;

